import React, { useState, useEffect, useMemo } from 'react';
import { getAdminBookings, updateAdminBookingStatus } from '../../api/listingService';
import { Card, CardContent, CardHeader, CardTitle } from '../ui/card';
import { Button } from '../ui/button';
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from '../ui/table';
import { Badge } from '../ui/badge';
import { CalendarCheck, User, Building, Utensils, Clock, CheckCircle, XCircle } from 'lucide-react';
import { toast } from "sonner";
import { Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle } from '../ui/dialog';
import Pagination from '../ui/Pagination';

const BookingsManagement = () => {
    const [bookings, setBookings] = useState([]);
    const [loading, setLoading] = useState(true);
    const [selectedBooking, setSelectedBooking] = useState(null);
    const [showActionDialog, setShowActionDialog] = useState(false);
    const [actionType, setActionType] = useState('');
    const [currentPage, setCurrentPage] = useState(1);
    const itemsPerPage = 8;

    const fetchBookings = async () => {
        try {
            setLoading(true);
            // You'll need to implement getAdminBookings in your listingService.js
            const data = await getAdminBookings();
            setBookings(data || []);
        } catch (error) {
            console.error(error);
            toast.error('Failed to fetch bookings.');
        } finally {
            setLoading(false);
        }
    };

    useEffect(() => {
        fetchBookings();
    }, []);

    const handleBookingAction = async (bookingId, action) => {
        try {
            await updateAdminBookingStatus(bookingId, action);
            toast.success(`Booking ${action === 'approve' ? 'approved' : 'rejected'} successfully.`);
            fetchBookings();
            setShowActionDialog(false);
        } catch (error) {
            toast.error('Failed to update booking status.');
        }
    };

    const getStatusColor = (status) => {
        switch (status.toLowerCase()) {
            case 'pending':
                return 'warning';
            case 'approved':
                return 'default';
            case 'confirmed':
                return 'success';
            case 'rejected':
            case 'cancelled':
                return 'destructive';
            case 'expired':
                return 'secondary';
            default:
                return 'secondary';
        }
    };

    const paginatedBookings = useMemo(() => {
        const startIndex = (currentPage - 1) * itemsPerPage;
        return bookings.slice(startIndex, startIndex + itemsPerPage);
    }, [bookings, currentPage]);

    const handlePageChange = (page) => {
        setCurrentPage(page);
        window.scrollTo({ top: 0, behavior: 'smooth' });
    };

    if (loading) {
        return (
            <div className="container mx-auto px-4 py-8">
                <div className="bg-white rounded-xl border-2 border-gray-200 p-6">
                    <div className="h-8 w-44 bg-gray-200 rounded animate-pulse mb-2"></div>
                    <div className="h-5 w-56 bg-gray-200 rounded animate-pulse mb-6"></div>
                    <div className="h-10 w-full bg-gray-200 rounded animate-pulse mb-6"></div>
                    <div className="space-y-3">
                        {[1, 2, 3, 4, 5, 6, 7, 8].map(i => (
                            <div key={i} className="h-16 w-full bg-gray-100 rounded-lg flex items-center px-4 animate-pulse">
                                <div className="w-32 bg-gray-200 rounded mb-2"></div>
                                <div className="w-40 bg-gray-200 rounded mb-2 ml-4"></div>
                                <div className="w-24 bg-gray-200 rounded ml-4"></div>
                                <div className="w-20 bg-gray-200 rounded ml-auto"></div>
                            </div>
                        ))}
                    </div>
                </div>
            </div>
        );
    }

    return (
        <div className="container mx-auto px-4 py-8">
            <Card className="border-2 border-gray-200">
                <CardHeader>
                    <CardTitle className="flex items-center gap-2 text-2xl">
                        <CalendarCheck className="h-6 w-6 text-green-600" />
                        Bookings Management
                    </CardTitle>
                    <p className="text-gray-600 mt-2">
                        Monitor and manage all booking requests across the platform
                    </p>
                </CardHeader>
                <CardContent>
                    <Table>
                        <TableHeader>
                            <TableRow>
                                <TableHead>Student</TableHead>
                                <TableHead>Property</TableHead>
                                <TableHead>Type</TableHead>
                                <TableHead>Start Date</TableHead>
                                <TableHead>Status</TableHead>
                                <TableHead className="text-right">Actions</TableHead>
                            </TableRow>
                        </TableHeader>
                        <TableBody>
                            {paginatedBookings.length > 0 ? paginatedBookings.map(booking => (
                                <TableRow key={booking.booking_id}>
                                    <TableCell className="min-w-[160px]">
                                        <div className="flex items-center gap-3">
                                            {booking.studentPhoto ? (
                                                <img
                                                    src={booking.studentPhoto}
                                                    alt={booking.studentName}
                                                    className="h-8 w-8 rounded-full object-cover flex-shrink-0"
                                                />
                                            ) : (
                                                <div className="h-8 w-8 rounded-full bg-gray-200 flex items-center justify-center flex-shrink-0">
                                                    <User className="h-4 w-4 text-gray-500" />
                                                </div>
                                            )}
                                            <div className="min-w-0">
                                                <div className="font-medium truncate">{booking.studentName}</div>
                                                {booking.studentEmail && (
                                                    <div className="text-sm text-gray-500 truncate">{booking.studentEmail}</div>
                                                )}
                                            </div>
                                        </div>
                                    </TableCell>
                                    <TableCell className="min-w-[200px] max-w-[280px]">
                                        <div className="font-medium">{booking.itemName}</div>
                                        <div className="text-sm text-gray-500 whitespace-normal break-words leading-snug mt-0.5">{booking.itemAddress}</div>
                                    </TableCell>
                                    <TableCell className="w-[100px]">
                                        <Badge
                                            className={`flex items-center gap-1 whitespace-nowrap ${booking.item_type === 'room'
                                                ? 'bg-blue-100 text-blue-800 hover:bg-blue-100 border-blue-200'
                                                : 'bg-orange-100 text-orange-800 hover:bg-orange-100 border-orange-200'
                                                }`}
                                        >
                                            {booking.item_type === 'room'
                                                ? <Building className="h-3 w-3" />
                                                : <Utensils className="h-3 w-3" />
                                            }
                                            <span className="capitalize">{booking.item_type}</span>
                                        </Badge>
                                    </TableCell>
                                    <TableCell className="w-[120px]">
                                        <div className="flex items-center gap-2">
                                            <Clock className="h-4 w-4 text-gray-500 flex-shrink-0" />
                                            <span className="truncate">{booking.start_date}</span>
                                        </div>
                                    </TableCell>
                                    <TableCell className="w-[100px]">
                                        <Badge variant={getStatusColor(booking.status)} className="capitalize whitespace-nowrap">
                                            {booking.status}
                                        </Badge>
                                    </TableCell>
                                    <TableCell className="text-right">
                                        {booking.status === 'pending' ? (
                                            <div className="flex items-center justify-end gap-1.5">
                                                <Button
                                                    size="sm"
                                                    variant="outline"
                                                    className="h-8 px-2 text-green-700 hover:bg-green-50 border-green-300 text-xs"
                                                    onClick={() => {
                                                        setSelectedBooking(booking);
                                                        setActionType('approve');
                                                        setShowActionDialog(true);
                                                    }}
                                                >
                                                    <CheckCircle className="h-3.5 w-3.5 mr-1" />
                                                    Approve
                                                </Button>
                                                <Button
                                                    size="sm"
                                                    variant="outline"
                                                    className="h-8 px-2 text-red-700 hover:bg-red-50 border-red-300 text-xs"
                                                    onClick={() => {
                                                        setSelectedBooking(booking);
                                                        setActionType('reject');
                                                        setShowActionDialog(true);
                                                    }}
                                                >
                                                    <XCircle className="h-3.5 w-3.5 mr-1" />
                                                    Reject
                                                </Button>
                                            </div>
                                        ) : (
                                            <span className="text-xs text-gray-400">Completed</span>
                                        )}
                                    </TableCell>
                                </TableRow>
                            )) : (
                                <TableRow>
                                    <TableCell colSpan="6" className="text-center py-8">
                                        <div className="flex flex-col items-center justify-center">
                                            <CalendarCheck className="h-8 w-8 text-gray-400 mb-2" />
                                            <p className="text-gray-500">No bookings found</p>
                                        </div>
                                    </TableCell>
                                </TableRow>
                            )}
                        </TableBody>
                    </Table>
                    <Pagination
                        currentPage={currentPage}
                        totalItems={bookings.length}
                        itemsPerPage={itemsPerPage}
                        onPageChange={handlePageChange}
                    />
                </CardContent>
            </Card>

            {/* Action Confirmation Dialog */}
            <Dialog open={showActionDialog} onOpenChange={setShowActionDialog}>
                <DialogContent className="sm:max-w-[425px]">
                    <DialogHeader>
                        <DialogTitle className="text-xl">
                            {actionType === 'approve' ? 'Approve Booking' : 'Reject Booking'}
                        </DialogTitle>
                        <DialogDescription>
                            Are you sure you want to {actionType} this booking request from
                            <span className="font-semibold"> {selectedBooking?.studentName}</span>?
                        </DialogDescription>
                    </DialogHeader>
                    <DialogFooter>
                        <Button variant="outline" onClick={() => setShowActionDialog(false)}>
                            Cancel
                        </Button>
                        <Button
                            variant={actionType === 'approve' ? 'default' : 'destructive'}
                            onClick={() => {
                                if (selectedBooking) {
                                    handleBookingAction(selectedBooking.booking_id, actionType);
                                }
                            }}
                        >
                            {actionType === 'approve' ? 'Approve' : 'Reject'}
                        </Button>
                    </DialogFooter>
                </DialogContent>
            </Dialog>
        </div>
    );
};

export default BookingsManagement;